  if (result.code !== 0) return { ok: false }
  const facts = {}
  for (const line of result.stdout.split('\n')) {
    const index = line.indexOf('=')
    if (index <= 0) continue
    facts[line.slice(0, index).trim()] = line.slice(index + 1).trim()
  }
  return {
    ok: true,
    user: facts.user ?? '',
    host: facts.host ?? '',
    kernel: facts.kernel ?? '',
    up: facts.up ?? '',
    at: Date.now(),
  }
}

