{"command":"$ErrorActionPreference='SilentlyContinue'
$node="C:\Users\TestFox\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\node\bin\node.exe"
$script=@'
const fs=require('node:fs');
const p='C:/Users/TestFox/AppData/Local/Programs/DeepSeek Harness/resources/app.asar';
const fd=fs.openSync(p,'r');
const b=Buffer.alloc(16); fs.readSync(fd,b,0,16,0);
const s=b.readUInt32LE(12);
const h=Buffer.alloc(s); fs.readSync(fd,h,0,s,16);
const header=JSON.parse(h.toString('utf8'));
function walk(node,path,out){
  for(const k of Object.keys(node.files||{})){
    const child=node.files[k]; const fp=path?path+'/'+k:k;
    if(child.files) walk(child,fp,out); else out.push(fp);
  }
}
const files=[]; walk(header,'',files);
const hits=files.filter(f=>/sidebar-terminal|terminal/i.test(f));
console.log('total files',files.length);
console.log(hits.slice(0,60).join('\n'));
fs.closeSync(fd);
'@
$script | Out-File -FilePath "$env:TEMP\asar-ls.mjs" -Encoding utf8
& $node "$env:TEMP\asar-ls.mjs"","description":"List terminal-related files inside app.asar","timeoutMs":120000}

