{"command": "$ErrorActionPreference='SilentlyContinue'
$node="C:\Users\TestFox\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\node\bin\node.exe"
$script=@'
const fs=require('node:fs');
const p='C:/Users/TestFox/AppData/Local/Programs/DeepSeek Harness/resources/app.asar';
const fd=fs.openSync(p,'r');
const b=Buffer.alloc(16); fs.readSync(fd,b,0,16,0);
const s=b.readUInt32LE(12);
const h=Buffer.alloc(s); fs.readSync(fd,h,0,s,16);
const header=JSON.parse(h.toString('utf8'));
function find(node,path){
  const parts=path.split('/');
  let cur=node;
  for(const part of parts){
    if(part===''||part==='.') continue;
    if(!cur.files||!cur.files[part]) return null;
    cur=cur.files[part];
  }
  return cur;
}
function readFile(node){
  if(!node||node.files||!node.size) return null;
  const out=Buffer.alloc(node.size);
  const off=node.offset.startsWith('0x')?parseInt(node.offset,16):Number(node.offset);
  fs.readSync(fd,out,0,node.size,16+s+off);
  return out.toString('utf8');
}
const wants=process.argv.slice(2);
const outdir='C:/Users/TestFox/AppData/Local/Temp/asar-x';
fs.mkdirSync(outdir,{recursive:true});
for(const w of wants){
  const node=find(header,w);
  if(!node){console.log('MISS',w);continue;}
  const content=readFile(node);
  if(content===null){console.log('DIR ',w);continue;}
  const base=w.split('/').pop();
  const dst=outdir+'/'+base;
  fs.writeFileSync(dst,content);
  console.log('OK  ',w,'->',dst,content.length,'bytes');
}
fs.closeSync(fd);
'@
