    let targetPort = port

    if (mode === 'tunnel') {
      const local = await freePort()
      const current = this.#settings
      const sshArgs = ['-N', '-o', 'BatchMode=yes', '-o', 'ExitOnForwardFailure=yes', '-o', 'ServerAliveInterval=30', '-o', 'StrictHostKeyChecking=accept-new']
