    socket.setNoDelay?.(true)
    this.#socket = socket
    await new Promise((resolve, reject) => {
      const fail = error => {
        socket.destroy()
        this.#dispose()
        reject(new Error(`连接 VNC 失败：${error?.message ?? error}`))
