    socket.on('error', error => {
      this.#log.warn?.(`dzrobot-ssh vnc: socket error (${error?.message ?? error})`)
      this.#finish()
    })
    socket.on('close', () => this.#finish())
    this.#log.info?.(`dzrobot-ssh vnc: bridged ${this.describe()}`)
