  const decoded = Buffer.from(result.stdout.toString('utf8').trim(), 'base64').toString('utf8')
  const fields = decoded.split('\0')
  if (fields[0] === '' || fields.length < 4) return { ok: false, error: '文件不存在' }
  const [name, kind, size, mtime] = fields
