          logger.warn?.(`dzrobot-ssh: download failed (${transferred.stderr})`)
          res.destroy()
        }
        return undefined
      }
      if (method === 'POST' && route === '/upload') {
        const requested = url.searchParams.get('path') ?? ''
        if (requested === '') return send(400, { ok: false, error: '缺少 path' })
