.dzr_seg button{border:0;background:transparent;color:var(--dsw-alias-label-secondary);font:inherit;font-size:12px;padding:4px 12px;border-radius:8px;cursor:pointer;white-space:nowrap}
.dzr_seg button[aria-pressed="true"]{background:var(--dsw-alias-bg-layer-3);color:var(--dsw-alias-label-primary);box-shadow:0 1px 2px rgb(0 0 0 / 12%)}
.dzr_pbody{flex:1;min-height:0;display:flex;flex-direction:column;position:relative}
