         * Hand the typed password to the *live* RFB object.
         *
         * noVNC's library renders no prompt of its own: it fires
         * `credentialsrequired` and waits for the embedding app to answer with
         * `sendCredentials`. Rebuilding the RFB object instead would work but
         * throws away the connection state, so the panel keeps this button.
         */
        const submitPassword = useCallback(() => {
          const rfb = rfbRef.current
          if (rfb === null || password === '') return
          try {
            rfb.sendCredentials({ password })
            setNeedPassword(false)
            setMessage('')
            diag('vnc.sendCredentials', { length: password.length })
          } catch (error) {
            setMessage(String(error?.message ?? error))
          }
        }, [password])

