diffs.newText:
def vnc_key(pw):
    # Key = first 8 bytes of the password (zero padded), each byte bit-reversed.
    raw_pw = pw.encode('utf-8') if isinstance(pw, str) else pw
    return bytes(int(format(b, '08b')[::-1], 2) for b in raw_pw[:8].ljust(8, b'\0'))

def decrypt(cand):
    key = vnc_key(cand)

