{"file_path": "D:\User\Desktop\dzrobot_v10.05\dsh-plugin-dzrobot-ssh\src\files.js", "new_string": "  const result = await remote(settings, `base64 -w0 -- ${quote(path)}`, { signal, timeoutMs: 25000 })
  if (result.code !== 0) return { ok: false, error: remoteError(result.stderr, '读取失败') }
  const buffer = Buffer.from(result.stdout.toString('utf8').trim(), 'base64')

  // A NUL byte is the cheapest reliable binary tell, but it is not the only one:
  // ~21% of 400 random bytes contain no NUL at all. So the decoded prefix is also
  // judged on its shape — replacement characters (invalid UTF-8) and control
  // bytes are what actually distinguishes "not text" from "text".
  const prefix = buffer.subarray(0, 8000)
  if (prefix.includes(0)) return { ok: true, binary: true, size: buffer.length, path: info.path }

  const text = buffer.toString('utf8')
  const head = text.slice(0, 8000)
  let suspicious = 0
  for (const character of head) {
    const code = character.codePointAt(0)
    if (code === 0xfffd) suspicious += 2
    else if (code < 9 || (code > 13 && code < 32) || code === 127) suspicious += 1
  }
  if (suspicious * 100 > head.length * 2) {
    return { ok: true, binary: true, size: buffer.length, path: info.path }
  }

  return {
    ok: true,
    binary: false,
    path: info.path,
    size: buffer.length,
    mtime: info.mtime,
    text,
  }
}", "old_string": "  const result = await remote(settings, `base64 -w0 -- ${quote(path)}`, { signal, timeoutMs: 25000 })
