 * Walk the RFB version + security handshake far enough to prove the tunnel
 * carries a real multi-step conversation, not just the first packet.
 *
 * It deliberately stops once the 16-byte challenge arrives and does NOT answer
 * it: completing the handshake with a wrong password is a *failed* VNC
 * authentication, and TigerVNC blacklists a client address after a handful of
 * those for several minutes. A test must not lock the operator's own laptop out
 * of the car's desktop, and three round-trips already prove the framing.
 */
async function rfbHandshake() {
  return new Promise((resolve, reject) => {
    const socket = new WebSocket(`ws://127.0.0.1:${port}/api/dzrobot-ssh/vnc`)
    socket.binaryType = 'arraybuffer'
    const notes = []
    let received = Buffer.alloc(0)
    let want = 12
    let stage = 'version'
    const finish = (error, value) => {
      clearTimeout(timer)
      try { socket.close() } catch { /* already closed */ }
      if (error) reject(error)
      else resolve(value)
    }
    const timer = setTimeout(() => finish(new Error('RFB handshake timed out')), 20000)

    const advance = () => {
      if (received.length < want) return
      const chunk = received.subarray(0, want)
      received = received.subarray(want)
      switch (stage) {
        case 'version':
          notes.push(`version=${chunk.toString('latin1').trim()}`)
          stage = 'count'; want = 1
          break
        case 'count': {
          const types = chunk[0]
          notes.push(`securityTypes=${types}`)
          if (types === 0) {
            // RFB's "no security types" answer is a refusal that carries a reason
            // string; it is what a blacklisted client receives.
            finish(new Error('the car refused the connection (0 security types offered — likely a VNC blacklist after failed logins)'))
            return
          }
          stage = 'types'; want = types
          break
        }
        case 'types': {
          const offered = [...chunk]
          notes.push(`offered=[${offered.join(',')}]`)
          const chosen = offered.includes(2) ? 2 : (offered.includes(1) ? 1 : null)
          if (chosen === null) {
            finish(new Error(`no VncAuth/None offered: ${offered.join(',')}`))
            return
          }
          notes.push(`chose=${chosen}`)
          socket.send(new Uint8Array([chosen]))
          stage = 'challenge'; want = 16
          break
        }
        case 'challenge':
          notes.push(`challenge=${chunk.length}B`)
          // Stop here on purpose: answering would be a real authentication
          // attempt, and a wrong one counts against the blacklist.
          finish(null, { notes, gotChallenge: chunk.length === 16 })
          return
        default:
          break
      }
      if (received.length > 0) advance()
    }

    socket.onopen = () => socket.send(new TextEncoder().encode('RFB 003.008\n'))
    socket.onmessage = event => { received = Buffer.concat([received, Buffer.from(event.data)]); advance() }
    socket.onerror = () => finish(new Error('websocket errored'))
  })
}

const handshake = await rfbHandshake()
