{"content": "<!doctype html>
<!--
  The VNC screen, served from this plugin's own http origin.

  Why a separate document instead of importing noVNC into the panel: the app's
  main page is loaded under a custom `dsh-app://` scheme, and ES module loading
  does not work there — `import()` of the vendored tree fails with "Failed to
  fetch dynamically imported module". Inside this document the origin is plain
  http, so `import './novnc/core/rfb.js'` and its 56 relative imports are ordinary
  same-origin module loads, and the WebSocket is same-origin too.

  The panel embeds this in an iframe and talks to it over postMessage, so the
  host page never needs to know anything about RFB.
-->
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>小车 VNC</title>
<style>
  :root { color-scheme: dark; }
  html, body { margin: 0; height: 100%; background: #101418; overflow: hidden;
    font: 12.5px/1.5 -apple-system, "Segoe UI", "Microsoft YaHei", system-ui, sans-serif; color: #c9d1d9; }
  #wrap { display: flex; flex-direction: column; height: 100%; }
  #bar { display: flex; align-items: center; gap: 8px; padding: 6px 10px; background: #171c22;
    border-bottom: 1px solid #262d36; flex: none; }
  #status { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  #status.err { color: #ff8a80; }
  #status.ok { color: #7ee787; }
  #bar button { font: inherit; padding: 3px 9px; border-radius: 7px; border: 1px solid #333c47;
    background: #1d242c; color: inherit; cursor: pointer; }
  #bar button:hover:not(:disabled) { border-color: #4b5b6b; }
  #bar button:disabled { opacity: .45; cursor: default; }
  #spacer { margin-left: auto; }
  #stage { position: relative; flex: 1; min-height: 0; background: #000; }
  #screen { width: 100%; height: 100%; }
  #screen canvas { display: block; margin: 0 auto; max-width: 100%; max-height: 100%; }
  #ask { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }
  #ask[hidden] { display: none; }
  #askbox { display: flex; flex-direction: column; gap: 9px; align-items: center; padding: 16px 18px;
    border-radius: 12px; border: 1px solid #333c47; background: #1a2027; box-shadow: 0 12px 40px rgb(0 0 0 / 45%); }
  #askbox p { margin: 0; font-size: 12px; }
  #askbox input { width: 210px; text-align: center; font: inherit; padding: 5px 9px; border-radius: 8px;
    border: 1px solid #3a444f; background: #10151a; color: inherit; }
</style>
</head>
<body>
<div id="wrap">
  <div id="bar">
    <span id="status">未连接</span>
    <button id="reconnect" hidden>重新连接</button>
    <span id="spacer"></span>
    <button id="cad" disabled title="Ctrl+Alt+Del">Ctrl+Alt+Del</button>
  </div>
  <div id="stage">
    <div id="screen"></div>
    <div id="ask" hidden>
      <form id="askbox">
        <p id="asktext">这台车的 VNC 需要密码</p>
        <input id="pw" type="password" autocomplete="current-password" placeholder="VNC 密码">
        <button type="submit" id="send">登录</button>
      </form>
    </div>
  </div>
</div>
<script type="module">
  import RFB from './novnc/core/rfb.js'

  const screen = document.getElementById('screen')
  const status = document.getElementById('status')
  const cad = document.getElementById('cad')
  const reconnect = document.getElementById('reconnect')
  const ask = document.getElementById('ask')
  const asktext = document.getElementById('asktext')
  const pw = document.getElementById('pw')

  let rfb = null
  let desktop = ''

  /** Tell the embedding panel what is happening; it owns no RFB knowledge. */
  const report = (type, data = {}) => {
    try { window.parent?.postMessage({ source: 'dzrobot-vnc', type, ...data }, '*') } catch { /* no parent */ }
  }

  const setStatus = (text, tone = '') => {
    status.textContent = text
    status.className = tone
  }

  function teardown() {
    const current = rfb
    rfb = null
    try { current?.disconnect() } catch { /* already gone */ }
    screen.innerHTML = ''
    cad.disabled = true
  }

  function connect(password) {
    teardown()
    setStatus('正在连接桌面…')
    reconnect.hidden = true
    ask.hidden = true
    report('connecting')
    const scheme = location.protocol === 'https:' ? 'wss:' : 'ws:'
    const url = `${scheme}//${location.host}/api/dzrobot-ssh/vnc`
    try {
      // No password supplied means "ask the server, then prompt": the car's
      // password file is a hash on its own disk, so it cannot be pre-derived.
      const credentials = password === undefined || password === '' ? undefined : { password }
      rfb = new RFB(screen, url, {
        credentials,
        wsProtocols: ['binary'],
        shared: true,
        resizeSession: false,
        scaleViewport: true,
        background: '#000',
      })
    } catch (error) {
      setStatus(`无法启动 VNC：${error?.message ?? error}`, 'err')
      report('failed', { message: String(error?.message ?? error) })
      return
    }

    rfb.addEventListener('connect', () => {
      ask.hidden = true
      cad.disabled = false
      setStatus(`已连接${desktop === '' ? '' : ` · ${desktop}`}`, 'ok')
      report('connected', { desktop })
    })
    rfb.addEventListener('credentialsrequired', () => {
      ask.hidden = false
      asktext.textContent = '这台车的 VNC 需要密码（与 Linux 登录密码是两回事）'
      pw.value = ''
      pw.focus()
      setStatus('等待输入 VNC 密码…')
      report('credentials')
    })
    rfb.addEventListener('securityfailure', event => {
      const reason = String(event?.detail?.reason ?? '认证失败')
      // TigerVNC refuses a client outright after a few failed logins; it reads as
      // a broken plugin unless the waiting time is named.
      const blacklisted = /too many security failures|security failure/i.test(reason)
      ask.hidden = !blacklisted
      setStatus(blacklisted
        ? '小车暂时拒绝本机（连续认证失败被拉黑，默认约 10 分钟），稍后再试。'
        : `认证失败：${reason}`, 'err')
      report('failed', { message: reason, blacklisted })
    })
    rfb.addEventListener('disconnect', event => {
      cad.disabled = true
      reconnect.hidden = false
      const clean = event?.detail?.clean !== false
      setStatus(clean ? '桌面已断开' : '连接异常中断', clean ? '' : 'err')
      report('disconnected', { clean })
    })
    rfb.addEventListener('desktopname', event => {
      desktop = String(event?.detail?.name ?? '')
      if (rfb !== null) setStatus(`已连接 · ${desktop}`, 'ok')
    })
  }

  document.getElementById('askbox').addEventListener('submit', event => {
    event.preventDefault()
    const value = pw.value
    if (value === '' || rfb === null) return
    try {
      rfb.sendCredentials({ password: value })
      ask.hidden = true
      setStatus('正在认证…')
      report('credentials-sent')
    } catch (error) {
      setStatus(`发送密码失败：${error?.message ?? error}`, 'err')
    }
  })

  cad.addEventListener('click', () => { try { rfb?.sendCtrlAltDel() } catch { /* not connected */ } })
  reconnect.addEventListener('click', () => connect(pw.value))

  window.addEventListener('message', event => {
    const message = event.data
    if (message === null || typeof message !== 'object' || message.source !== 'dzrobot-panel') return
    if (message.type === 'connect') connect(message.password ?? '')
    else if (message.type === 'password' && rfb !== null) {
      try { rfb.sendCredentials({ password: message.password ?? '' }) } catch { /* ignore */ }
    } else if (message.type === 'disconnect') teardown()
    else if (message.type === 'cad') { try { rfb?.sendCtrlAltDel() } catch { /* ignore */ } }
  })

  // The panel asks before dialing (a VNC session takes over the car's desktop
  // input, and an abandoned connection counts against TigerVNC's blacklist), but
  // an explicit query parameter is honoured for a standalone tab.
  const params = new URLSearchParams(location.search)
  report('ready')
  if (params.get('autoconnect') === '1') connect(params.get('password') ?? '')
  else setStatus('按“连接桌面”开始（或直接点这里）')
  document.getElementById('stage').addEventListener('dblclick', () => { if (rfb === null) connect(pw.value) })
</script>
</body>
</html>
