{"file_path": "D:\User\Desktop\dzrobot_v10.05\dsh-plugin-dzrobot-ssh\client.js", "new_string": "    /**
     * The VNC desktop, as an embedded document on this plugin's own http origin.
     *
     * Not an in-page noVNC instance, and that is deliberate: the app itself is
     * loaded under a custom `dsh-app://` scheme where ES module loading fails
     * ("Failed to fetch dynamically imported module") and where a WebSocket built
     * from `location.host` targets a host literally named `app`. The iframe is
     * served over http by the host half, so inside it `import './novnc/core/rfb.js'`
     * and the WebSocket are plain same-origin operations — and the panel only has
     * to relay messages, not understand RFB.
     *
     * Dialing stays explicit: a VNC session takes over the car's desktop input,
     * and an abandoned connection counts against TigerVNC's blacklist.
     */
    function makeVncView(ctx, t) {
      return function VncView({ settings, origin }) {
        const frameRef = useRef(null)
        const [phase, setPhase] = useState('idle')
        const [message, setMessage] = useState('')
        const [needPassword, setNeedPassword] = useState(false)
        const [password, setPassword] = useState(settings.vncPassword ?? '')
        const [desktop, setDesktop] = useState('')

        const post = useCallback(payload => {
          try { frameRef.current?.contentWindow?.postMessage({ source: 'dzrobot-panel', ...payload }, '*') }
          catch { /* frame not ready */ }
        }, [])

        useEffect(() => {
          const onMessage = event => {
            const data = event.data
            if (data === null || typeof data !== 'object' || data.source !== 'dzrobot-vnc') return
            if (data.type === 'ready' || data.type === 'connecting') { setPhase('connecting'); setMessage('') }
            else if (data.type === 'connected') { setPhase('connected'); setDesktop(String(data.desktop ?? '')); setMessage('') }
            else if (data.type === 'credentials') { setNeedPassword(true); setPhase('auth') }
            else if (data.type === 'disconnected') { setPhase('disconnected'); setNeedPassword(false) }
            else if (data.type === 'failed') {
              setPhase('failed')
              setMessage(String(data.message ?? '失败'))
              setNeedPassword(data.blacklisted !== true)
            }
            diag(`vnc.${String(data.type ?? 'event')}`, { message: data.message, clean: data.clean })
          }
          window.addEventListener('message', onMessage)
          return () => window.removeEventListener('message', onMessage)
        }, [])

        const connect = useCallback(() => {
          setPhase('connecting')
          setMessage('')
          post({ type: 'connect', password })
        }, [post, password])

        const stop = useCallback(() => { post({ type: 'disconnect' }); setPhase('idle') }, [post])

        const submitPassword = useCallback(() => {
          if (password === '') return
          post({ type: 'password', password })
          setNeedPassword(false)
          setPhase('connecting')
        }, [post, password])

        const src = origin === '' ? '' : `${origin}/api/dzrobot-ssh/vnc.html`
        const tone = phase === 'connected' ? '' : (phase === 'failed' ? ' dzr_warn' : '')

        return h('div', { className: 'dzr_pbody' }, [
          h('div', { key: 'bar', className: 'dzr_toolbar' }, [
            h('button', {
              key: 'go', type: 'button', className: 'dzr_action primary',
              disabled: src === '', onClick: connect,
            }, phase === 'connected' ? t('vncReconnect') : t('vncConnect')),
            phase === 'idle' || phase === 'disconnected'
              ? null
              : h('button', { key: 'stop', type: 'button', className: 'dzr_action', onClick: stop }, t('vncDisconnect')),
            h('label', { key: 'pw', className: 'dzr_field', style: { minWidth: '150px', maxWidth: '210px' } }, [
              h('span', { key: 'l' }, t('vncPassword')),
              h('input', {
                key: 'i', className: 'dzr_input', type: 'password', value: password,
                placeholder: t('vncPasswordHint'),
                onChange: event => setPassword(event.target.value),
                onKeyDown: event => { if (event.key === 'Enter') connect() },
              }),
            ]),
            h('span', { key: 'state', className: `dzr_note${tone}` },
              phase === 'connecting' ? t('vncConnecting')
                : phase === 'auth' ? t('vncNeedPassword')
                  : phase === 'connected' ? `${t('vncConnected')}${desktop === '' ? '' : ` · ${desktop}`}`
                    : phase === 'failed' ? message
                      : phase === 'disconnected' ? t('vncDisconnected')
                        : (settings.vncMode === 'tunnel' ? 'ssh 隧道' : `${settings.vncHost || settings.host}:${settings.vncPort}`)),
            h('span', { key: 'sp', style: { marginLeft: 'auto' } }),
            h('span', { key: 'origin', className: 'dzr_note dzr_tag' }, src === '' ? '未取得服务地址' : new URL(src).host),
          ]),
          h('div', { key: 'stage', className: 'dzr_screen' }, [
            src === ''
              ? h('div', { key: 'noorigin', className: 'dzr_overlay' }, h('div', null, t('vncNoOrigin')))
              : h('iframe', {
                key: 'frame',
                ref: frameRef,
                src,
                title: t('viewVnc'),
                // The frame is same-plugin content served over http; it needs no
                // sandbox restrictions beyond not being scriptable by anything else,
                // and it must keep its own origin for the module import to work.
                allow: 'clipboard-read; clipboard-write',
                style: { width: '100%', height: '100%', border: '0', display: 'block', background: '#000' },
              }),
            needPassword
              ? h('div', { key: 'ask', className: 'dzr_overlay' }, h('div', { className: 'dzr_ask' }, [
                h('div', { key: 't' }, t('vncAskInFrame')),
                h('div', { key: 'h', className: 'dzr_note' }, t('vncPasswordHint')),
              ]))
              : null,
          ]),
        ])
      }
    }", "old_string": "    /**
     * The VNC desktop.
     *
     * noVNC is imported as a native ES module from this plugin's own origin, so
     * the browser resolves its 56-file import graph itself — the reason the tree
     * is vendored unmodified instead of being bundled.
     *
     * The RFB object owns its canvas, its input handling and its reconnect-free
     * stream framing; this component owns the connection's *lifecycle* — when to
     * dial, what to do when credentials come back, and tearing it down on unmount.
     */
    function makeVncView(ctx, t) {
      return function VncView({ settings }) {
        const hostRef = useRef(null)
        const rfbRef = useRef(null)
        const [phase, setPhase] = useState('idle')
        const [message, setMessage] = useState('')
        const [needPassword, setNeedPassword] = useState(false)
        const [password, setPassword] = useState(settings.vncPassword ?? '')
        const [desktop, setDesktop] = useState('')

        const stop = useCallback(() => {
          const rfb = rfbRef.current
          rfbRef.current = null
          try { rfb?.disconnect() } catch { /* already gone */ }
          if (hostRef.current !== null) hostRef.current.innerHTML = ''
        }, [])

        const start = useCallback(async passwordOverride => {
          if (hostRef.current === null) return
          stop()
          setPhase('connecting')
          setMessage('')
          setNeedPassword(false)
          try {
            const url = new URL('/api/dzrobot-ssh/novnc/core/rfb.js', location.href).href
            const module = await import(/* @vite-ignore */ url)
            const RFB = module.default
            const scheme = location.protocol === 'https:' ? 'wss:' : 'ws:'
            const secret = passwordOverride ?? password
            const rfb = new RFB(hostRef.current, `${scheme}//${location.host}/api/dzrobot-ssh/vnc`, {
              // An empty password is not "no password": it tells RFB to wait for
              // `credentialsrequired` and let the user type one, which is the
              // only workable default — the car's password file is hashed and
              // this plugin has no way to recover it.
              credentials: secret === '' ? undefined : { password: secret },
              wsProtocols: ['binary'],
              shared: true,
              // The desktop is 1280x800; letting RFB resize the car's session to
              // whatever the panel happens to be is wrong for a shared desktop.
              resizeSession: false,
              scaleViewport: true,
              background: '#000',
            })
            rfbRef.current = rfb
            rfb.addEventListener('connect', () => { setPhase('connected'); setMessage(''); diag('vnc.connect', {}) })
            rfb.addEventListener('disconnect', event => {
              if (rfbRef.current !== rfb) return
              rfbRef.current = null
              setPhase('disconnected')
              setMessage(event?.detail?.clean === false ? '连接异常中断' : '')
              diag('vnc.disconnect', { clean: event?.detail?.clean })
            })
            rfb.addEventListener('credentialsrequired', () => {
              setNeedPassword(true)
              setMessage('')
              diag('vnc.credentials', {})
            })
            rfb.addEventListener('securityfailure', event => {
              const reason = String(event?.detail?.reason ?? '认证失败')
              // TigerVNC refuses a client outright after a few failed logins
              // ("Too many security failures"), which reads as a broken plugin
              // unless it is named — and it clears on its own after a while.
              const blacklisted = /too many security failures|security failure/i.test(reason)
              setPhase('failed')
              setNeedPassword(!blacklisted)
              setMessage(blacklisted ? t('vncBlacklisted') : reason)
              diag('vnc.securityfailure', { reason, blacklisted })
            })
            rfb.addEventListener('desktopname', event => setDesktop(String(event?.detail?.name ?? '')))
            diag('vnc.start', { url: `${scheme}//${location.host}/api/dzrobot-ssh/vnc`, password: secret !== '' })
          } catch (error) {
            setPhase('failed')
            setMessage(String(error?.message ?? error))
            diag('vnc.error', { message: String(error?.message ?? error) })
          }
        }, [password, stop])

        /**
         * Hand the typed password to the *live* RFB object.
         *
         * noVNC's library renders no prompt of its own: it fires
         * `credentialsrequired` and waits for the embedding app to answer with
         * `sendCredentials`. Rebuilding the RFB object instead would work but
         * throws away the connection state, so the panel keeps this button.
         */
        const submitPassword = useCallback(() => {
          const rfb = rfbRef.current
          if (rfb === null || password === '') return
          try {
            rfb.sendCredentials({ password })
            setNeedPassword(false)
            setMessage('')
            diag('vnc.sendCredentials', { length: password.length })
          } catch (error) {
            setMessage(String(error?.message ?? error))
          }
        }, [password])

        // Dialing is explicit rather than automatic: a VNC session takes over
        // the car's desktop input, and that should be the user's decision even
        // though the panel is already open.
        useEffect(() => () => stop(), [stop])

        return h('div', { className: 'dzr_pbody' }, [
          h('div', { key: 'bar', className: 'dzr_toolbar' }, [
            h('button', {
              key: 'go', type: 'button', className: 'dzr_action primary',
              onClick: () => void start(),
            }, phase === 'connected' ? t('vncReconnect') : t('vncConnect')),
            phase === 'connected' || phase === 'connecting'
              ? h('button', { key: 'stop', type: 'button', className: 'dzr_action', onClick: stop }, t('vncDisconnect'))
              : null,
            h('button', {
              key: 'cad', type: 'button', className: 'dzr_action',
              disabled: phase !== 'connected',
              onClick: () => { try { rfbRef.current?.sendCtrlAltDel() } catch { /* not connected */ } },
            }, t('vncSendCad')),
            h('label', { key: 'pw', className: 'dzr_field', style: { minWidth: '150px', maxWidth: '210px' } }, [
              h('span', { key: 'l' }, t('vncPassword')),
              h('input', {
                key: 'i', className: 'dzr_input', type: 'password', value: password,
                placeholder: t('vncPasswordHint'),
                onChange: event => setPassword(event.target.value),
              }),
            ]),
            h('span', { key: 'state', className: `dzr_note${phase === 'failed' ? ' dzr_warn' : ''}` },
              phase === 'connecting' ? t('vncConnecting')
                : phase === 'connected' ? `${t('vncConnected')}${desktop === '' ? '' : ` · ${desktop}`}`
                  : phase === 'failed' ? t('vncSecurity', { detail: message })
                    : phase === 'disconnected' ? t('vncDisconnected')
                      : (settings.vncMode === 'tunnel' ? 'ssh 隧道' : `${settings.vncHost || settings.host}:${settings.vncPort}`)),
          ]),
          h('div', { key: 'screen', className: 'dzr_screen' }, [
            h('div', { key: 'host', ref: hostRef, style: { width: '100%', height: '100%' } }),
            // The overlay must appear during authentication too, which happens
            // while the connection is still in its `connecting` phase.
            needPassword || phase === 'idle' || phase === 'failed' || phase === 'disconnected'
              ? h('div', { key: 'overlay', className: 'dzr_overlay' }, [
                h('div', { key: 'msg' }, message === '' ? t('vncPointer') : message),
                // The car's VNC password is stored only as a DES-obfuscated file
                // on its own disk, so unless it was filled in above, the server
                // has to be asked — this is that prompt.
                needPassword ? h('div', { key: 'ask', className: 'dzr_ask' }, [
                  h('div', { key: 't' }, t('vncNeedPassword')),
                  h('input', {
                    key: 'i', className: 'dzr_input', type: 'password', autoFocus: true,
                    value: password, placeholder: t('vncPassword'),
                    onChange: event => setPassword(event.target.value),
                    onKeyDown: event => { if (event.key === 'Enter') submitPassword() },
