/**
 * The VNC desktop, as an embedded document on this plugin's own http origin.
 *
 * Not an in-page noVNC instance, and that is deliberate: the app itself is
 * loaded under a custom `dsh-app://` scheme where ES module loading fails
 * ("Failed to fetch dynamically imported module") and where a WebSocket built
 * from `location.host` targets a host literally named `app`. The iframe is
 * served over http by the host half, so inside it `import './novnc/core/rfb.js'`
 * and the WebSocket are plain same-origin operations — and the panel only has
 * to relay messages, not understand RFB.
 *
 * Dialing stays explicit: a VNC session takes over the car's desktop input,
 * and an abandoned connection counts against TigerVNC's blacklist.
 */
function makeVncView(ctx, t) {
  return function VncView({ settings, origin }) {
    const frameRef = useRef(null)
    const [phase, setPhase] = useState('idle')
    const [message, setMessage] = useState('')
    const [needPassword, setNeedPassword] = useState(false)
    const [password, setPassword] = useState(settings.vncPassword ?? '')
    const [desktop, setDesktop] = useState('')

    const post = useCallback(payload => {
      try { frameRef.current?.contentWindow?.postMessage({ source: 'dzrobot-panel', ...payload }, '*') }
      catch { /* frame not ready */ }
    }, [])

    useEffect(() => {
      const onMessage = event => {
        const data = event.data
        if (data === null || typeof data !== 'object' || data.source !== 'dzrobot-vnc') return
        if (data.type === 'ready' || data.type === 'connecting') { setPhase('connecting'); setMessage('') }
        else if (data.type === 'connected') { setPhase('connected'); setDesktop(String(data.desktop ?? '')); setMessage('') }
        else if (data.type === 'credentials') { setNeedPassword(true); setPhase('auth') }
        else if (data.type === 'disconnected') { setPhase('disconnected'); setNeedPassword(false) }
        else if (data.type === 'failed') {
          setPhase('failed')
          setMessage(String(data.message ?? '失败'))
          setNeedPassword(data.blacklisted !== true)
        }
        diag(`vnc.${String(data.type ?? 'event')}`, { message: data.message, clean: data.clean })
      }
      window.addEventListener('message', onMessage)
      return () => window.removeEventListener('message', onMessage)
    }, [])

    const connect = useCallback(() => {
      setPhase('connecting')
      setMessage('')
      post({ type: 'connect', password })
    }, [post, password])

    const stop = useCallback(() => { post({ type: 'disconnect' }); setPhase('idle') }, [post])

    const submitPassword = useCallback(() => {
      if (password === '') return
      post({ type: 'password', password })
      setNeedPassword(false)
      setPhase('connecting')
    }, [post, password])

    const src = origin === '' ? '' : `${origin}/api/dzrobot-ssh/vnc.html`
    const tone = phase === 'failed' ? ' dzr_warn' : ''

    return h('div', { className: 'dzr_pbody' }, [
      h('div', { key: 'bar', className: 'dzr_toolbar' }, [
        h('button', {
          key: 'go', type: 'button', className: 'dzr_action primary',
          disabled: src === '', onClick: connect,
        }, phase === 'connected' ? t('vncReconnect') : t('vncConnect')),
        phase === 'idle' || phase === 'disconnected'
          ? null
          : h('button', { key: 'stop', type: 'button', className: 'dzr_action', onClick: stop }, t('vncDisconnect')),
        h('label', { key: 'pw', className: 'dzr_field', style: { minWidth: '150px', maxWidth: '210px' } }, [
          h('span', { key: 'l' }, t('vncPassword')),
          h('input', {
            key: 'i', className: 'dzr_input', type: 'password', value: password,
            placeholder: t('vncPasswordHint'),
            onChange: event => setPassword(event.target.value),
            onKeyDown: event => { if (event.key === 'Enter') connect() },
          }),
        ]),
        needPassword
          ? h('button', { key: 'sendauth', type: 'button', className: 'dzr_action', onClick: submitPassword }, t('vncSubmitPassword'))
          : null,
        h('span', { key: 'state', className: `dzr_note${tone}` },
          phase === 'connecting' ? t('vncConnecting')
            : phase === 'auth' ? t('vncNeedPassword')
              : phase === 'connected' ? `${t('vncConnected')}${desktop === '' ? '' : ` · ${desktop}`}`
                : phase === 'failed' ? message
                  : phase === 'disconnected' ? t('vncDisconnected')
                    : (settings.vncMode === 'tunnel' ? 'ssh 隧道' : `${settings.vncHost || settings.host}:${settings.vncPort}`)),
        h('span', { key: 'sp', style: { marginLeft: 'auto' } }),
        h('span', { key: 'origin', className: 'dzr_note dzr_tag' }, src === '' ? t('vncNoOrigin') : origin.replace(/^https?:\/\//, '')),
      ]),
      h('div', { key: 'stage', className: 'dzr_screen' }, [
        src === ''
          ? h('div', { key: 'noorigin', className: 'dzr_overlay' }, h('div', null, t('vncNoOrigin')))
          : h('iframe', {
            key: 'frame',
            ref: frameRef,
            src,
            title: t('viewVnc'),
            // Served by this plugin itself, so it keeps its own origin (the
            // module import needs it) and is not sandboxed away from it.
            allow: 'clipboard-read; clipboard-write',
            style: { width: '100%', height: '100%', border: '0', display: 'block', background: '#000' },
          }),
        needPassword
          ? h('div', { key: 'ask', className: 'dzr_overlay' }, h('div', { className: 'dzr_ask' }, [
            h('div', { key: 't' }, t('vncAskInFrame')),
            h('div', { key: 'h', className: 'dzr_note' }, t('vncPasswordHint')),
          ]))
          : null,
      ]),
    ])

