  import RFB from './novnc/core/rfb.js'

  const screen = document.getElementById('screen')
  const ask = document.getElementById('ask')
  const asktext = document.getElementById('asktext')
  const pw = document.getElementById('pw')

  let rfb = null
  let desktop = ''
  const embedded = window.parent !== window

  /**
   * Observe every WebSocket this page opens.
   *
   * noVNC's `disconnect` event carries only `{clean}` — it cannot tell "the
   * handshake never started" from "the server closed with 1011 + a reason", and
   * that difference is exactly what diagnosis needs. This wrapper records the
   * URL and the raw open/error/close lifecycle (code + reason) so the panel's
   * diagnostics can carry them out; RFB constructs its socket later, so wrapping
   * now covers it.
   */
  const wsLog = []
  const NativeWebSocket = window.WebSocket
  window.WebSocket = class extends NativeWebSocket {
    constructor(url, protocols) {
      let built
      try {
        super(url, protocols)
        built = true
      } catch (error) {
        wsLog.push({ e: 'ctor-threw', url: String(url), message: String(error?.message ?? error) })
        throw error
      }
      wsLog.push({ e: 'ctor', url: String(url), protocols: Array.isArray(protocols) ? [...protocols] : String(protocols ?? '') })
      this.addEventListener('open', () => wsLog.push({ e: 'open' }))
      this.addEventListener('error', () => wsLog.push({ e: 'error' }))
      this.addEventListener('close', event => {
        wsLog.push({ e: 'close', code: event.code, reason: String(event.reason ?? ''), clean: event.wasClean })
      })
      void built
    }
  }
  window.addEventListener('error', event => {
    wsLog.push({ e: 'winerror', message: String(event?.message ?? '') })
  })

  /** Latest close outcome, for the disconnect report. */
  const lastClose = () => {
    for (let i = wsLog.length - 1; i >= 0; i -= 1) {
      if (wsLog[i].e === 'close') return wsLog[i]
    }
    return undefined
  }

