{"file_path":"D:\User\Desktop\dzrobot_v10.05\dsh-plugin-dzrobot-ssh\scripts\test-vnc-guard.mjs","content":"/**
 * The cached-address guard.
 *
 * `dialOrdered` remembers the address that answered, so an mDNS flake degrades
 * to "use what worked". This car roams between networks (observed: 192.168.43.17
 * and 10.230.128.188 on one day), so a cached address can name a *different*
 * host once the car moves. The bridge pumps raw desktop bytes, so it must not
 * forward anything to a peer that fails the RFB banner check.
 *
 * Run: node scripts/test-vnc-guard.mjs
 */

import net from 'node:net'
import assert from 'node:assert/strict'

const { VncBridge } = await import('../src/vnc.js')

const failures = []
const check = (label, run) => {
  try {
    run()
    console.log(`OK    ${label}`)
  } catch (error) {
    failures.push(`${label}: ${error?.message ?? error}`)
    console.log(`FAIL  ${label}\n      ${error?.message ?? error}`)
  }
}

/** A server that greets with `line` and then waits, never sending more. */
const greet = line => new Promise(resolve => {
  const server = net.createServer(socket => { socket.write(line) })
  server.listen(0, '127.0.0.1', () => resolve(server))
})

const close = server => new Promise(resolve => server.close(resolve))

// ── 1. a peer that speaks RFB passes the guard ────────────────────────────────
await (async () => {
  const server = await greet('RFB 003.008\n')
  const { port } = server.address()
  const bridge = new VncBridge({ host: '127.0.0.1', vncHost: '127.0.0.1', vncPort: port })
  try {
    await bridge.open()
    console.log('OK    banner check accepts a real RFB banner')
  } catch (error) {
    failures.push(`real banner rejected: ${error?.message ?? error}`)
    console.log(`FAIL  real banner rejected: ${error?.message ?? error}`)
  }
  bridge.close()
  await close(server)
})()

// ── 2. the held banner reaches the browser ───────────────────────────────────
// A verified banner is buffered, because the browser attaches its listener after
// the check; RFB servers never repeat it, so a dropped replay stalls noVNC.
await (async () => {
  const server = await greet('RFB 003.008\n')
  const { port } = server.address()
  const bridge = new VncBridge({ host: '127.0.0.1', vncHost: '127.0.0.1', vncPort: port })
  await bridge.open()
  const received = []
  bridge.onData(chunk => received.push(chunk.toString('latin1')))
  check('held banner is replayed to the browser', () => {
    assert.equal(received.join(''), 'RFB 003.008\n')
  })
  bridge.close()
  await close(server)
})()

// ── 3. a peer that is not VNC is refused, not bridged ────────────────────────
// This is the security property: no desktop bytes may flow to a host that merely
// reused the car's old address.
await (async () => {
