{"file_path":"D:\User\Desktop\dzrobot_v10.05\dsh-plugin-dzrobot-ssh\scripts\test-vnc-guard.mjs","new_string":"const { VncBridge } = await import('../src/vnc.js')

const failures = []
const check = (label, run) => {
  try {
    run()
    console.log(`OK    ${label}`)
  } catch (error) {
    failures.push(`${label}: ${error?.message ?? error}`)
    console.log(`FAIL  ${label}\n      ${error?.message ?? error}`)
  }
}

/**
 * Make the bridge dial `address` through the cached-address path.
 *
 * The guard exists for addresses that came from the cache, so the test has to
 * put one there: a name that never resolves (`ghost.invalid`) fails DNS lookup,
 * which is exactly what makes `dialOrdered` fall back to the last good address.
 * The cached entry is then what gets dialled — and, once rejected, deleted.
