{"content":"/**
 * The cached-address guard.
 *
 * `dialOrdered` remembers the address that answered, so an mDNS flake degrades to
 * "use what worked" instead of "give up". This car roams between networks
 * (observed: 192.168.43.17 and 10.230.128.188 on one day), so a cached address
 * can name a *different* host once the car moves. The bridge pumps raw desktop
 * bytes, so it must not forward a single one to a peer that fails the RFB banner
 * check — and a failed check must retire the cache entry.
 *
 * The cache is keyed by host and private to `src/vnc.js`, so every case primes
 * it the only way the product can: a real successful dial first, then a dial
 * against a name that cannot resolve (`*.invalid`), which is what sends
 * `dialOrdered` down the cache branch.
 *
 * Run: node scripts/test-vnc-guard.mjs
 */

import net from 'node:net'
import assert from 'node:assert/strict'

const { VncBridge } = await import('../src/vnc.js')

const failures = []
const check = (label, run) => {
  try {
    run()
    console.log(`OK    ${label}`)
  } catch (error) {
    failures.push(`${label}: ${error?.message ?? error}`)
    console.log(`FAIL  ${label}\n      ${error?.message ?? error}`)
  }
}

/** A server that greets with `line`, then goes quiet. */
const greet = line => new Promise(resolve => {
  const server = net.createServer(socket => {
    // The bridge tears its side down abruptly; an unhandled reset here would
    // crash the test run instead of reporting a verdict.
    socket.on('error', () => {})
    if (line !== undefined) socket.write(line)
  })
  server.listen(0, '127.0.0.1', () => resolve(server))
})

/** A server that accepts and never says anything. */
const silent = () => greet(undefined)

const close = server => new Promise(resolve => server.close(resolve))

/**
 * Remember `address:port` as the last good address for `name`.
 *
 * A successful dial is the only thing that writes the cache, so the priming
 * connection is made and dropped. `name` must be unresolvable (`.invalid`), which
 * is what makes the later dial fall back to the cached address.
 */
const primeCache = async (name, address, port) => {
  const warm = new VncBridge({ host: name, vncHost: name, vncPort: port })
  // Resolve the name by pointing the dial at the literal address: dns.lookup of a
  // `.invalid` name throws, so the cache is only populated on the literal path.
  await warm.open({ resolveTo: address })
  warm.close()
}

// ── 1. a cached address that still speaks RFB is bridged, banner included ──────
await (async () => {
  const server = await greet('RFB 003.008\n')
  const { port } = server.address()
  const name = 'dzrobot-guard-ok.invalid'
  await primeCache(name, '127.0.0.1', port)

  const bridge = new VncBridge({ host: name, vncHost: name, vncPort: port })
  await bridge.open()
  const received = []
  bridge.onData(chunk => received.push(chunk.toString('latin1')))
  check('cached RFB peer is bridged and its banner replayed', () => {
    assert.deepEqual(received, ['RFB 003.008\n'])
  })
  bridge.close()
  await close(server)
})()

// ── 2. a cached address that is NOT VNC is refused, and nothing is forwarded ──
// This is the security property.
await (async () => {
  const server = await greet('HTTP/1.1 200 OK\r\n\r\n')
  const { port } = server.address()
  const name = 'dzrobot-guard-wrong.invalid'
  await primeCache(name, '127.0.0.1', port)

  const bridge = new VncBridge({ host: name, vncHost: name, vncPort: port })
  let opened = false
  let reason = ''
  try {
    await bridge.open()
    opened = true
  } catch (error) {
    reason = String(error?.message ?? error)
  }
  const received = []
  bridge.onData(chunk => received.push(chunk.toString()))

  console.log(`     refused with: ${reason}`)
  check('non-VNC peer at a cached address is refused', () => {
    assert.equal(opened, false, 'bridge opened against a non-VNC peer')
  })
  check('no desktop bytes reach the browser', () => {
    assert.deepEqual(received, [], `forwarded ${JSON.stringify(received)}`)
  })
  bridge.close()
  await close(server)
})()

// ── 3. a cached address that accepts but never greets is refused ──────────────
await (async () => {
  const server = await silent()
  const { port } = server.address()
  const name = 'dzrobot-guard-silent.invalid'
  await primeCache(name, '127.0.0.1', port)

  const bridge = new VncBridge({ host: name, vncHost: name, vncPort: port })
  let opened = false
  try {
    await bridge.open()
    opened = true
  } catch { /* expected */ }
  check('silent peer at a cached address is refused', () => {
    assert.equal(opened, false, 'bridge opened against a peer that never greets')
  })
  bridge.close()
  server.close()
})()

// ── 4. a failed check retires the cache, so the next dial re-resolves ─────────
// Otherwise one bad verdict would keep poisoning every later attempt.
await (async () => {
  const impostor = await greet('nope\n')
  const impostorPort = impostor.address().port
  const name = 'dzrobot-guard-poison.invalid'

  // Prime with the impostor's address under a *different* name is not possible
  // (the cache is keyed by the dialed name), so prime under `name` itself.
  await primeCache(name, '127.0.0.1', impostorPort)
  const bridge = new VncBridge({ host: name, vncHost: name, vncPort: impostorPort })
  let refused = false
  try { await bridge.open() } catch { refused = true }
  check('impostor at a cached address is refused', () => {
    assert.equal(refused, true, 'bridge opened against an impostor')
  })
  bridge.close()

  // The real car now answers on the same port. Because the refusal retired the
  // cache and the name is still unresolvable, the dial must fail outright rather
  // than keep talking to whoever was cached.
  const real = await greet('RFB 003.008\n')
  check('a retired cache is not silently reused', async () => {
    // Rebind is not possible on the same port while `real` listens, so instead
    // assert the cache no longer answers: a fresh dial to the impostor port fails
    // the banner check again, which proves the code path re-runs per attempt
    // rather than trusting a stale verdict.
    const again = new VncBridge({ host: name, vncHost: name, vncPort: real.address().port })
    let ok = false
    try {
      await again.open()
      ok = true
      again.close()
    } catch { /* refused, as expected for an unresolvable name */ }
    assert.equal(ok, false, 'a dial with no cache and no DNS must not succeed')
  })
  bridge.close()
  await close(impostor)
  real.close()
})()

if (failures.length > 0) {
  console.log('\nFAILURES:')
  for (const failure of failures) console.log(' -', failure)
  process.exitCode = 1
