/** A server that greets with `line`, then goes quiet. */
const greet = line => new Promise(resolve => {
  const server = net.createServer(socket => {
    // The bridge tears its side down abruptly; an unhandled reset here would
    // crash the test run instead of reporting a verdict.
    socket.on('error', () => {})
    if (line !== undefined) socket.write(line)
  })
  server.listen(0, '127.0.0.1', () => resolve(server))
})

/** A server that accepts and never says anything. */
const silent = () => greet(undefined)

const close = server => new Promise(resolve => server.close(resolve))

/**
 * Remember `address:port` as the last good address for `name`.
 *
 * A successful dial is the only thing that writes the cache, so the priming
 * connection is made and dropped. `name` must be unresolvable (`.invalid`), which
 * is what makes the later dial fall back to the cached address.
 */
const primeCache = async (name, address, port) => {
  const warm = new VncBridge({ host: name, vncHost: name, vncPort: port })
  // Resolve the name by pointing the dial at the literal address: dns.lookup of a
  // `.invalid` name throws, so the cache is only populated on the literal path.
  await warm.open({ resolveTo: address })
  warm.close()
}

