content.arguments:
{"command":"$ErrorActionPreference='Continue'
$node="C:\Users\TestFox\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\node\bin\node.exe"
$d="D:\User\Desktop\dzrobot_v10.05\dsh-plugin-dzrobot-ssh"
foreach ($t in @('test-host.mjs','test-client.mjs','test-vnc-guard.mjs')) {
  $r = & $node "$d\scripts\$t" 2>&1 | Out-String
  $line = ($r -split "`n" | Where-Object { $_ -match 'PASSED|FAIL' }) -join ' | '
  "{0,-22} {1}" -f $t, $line.Trim()
}
"=== live car ==="
& $node "$d\scripts\test-live-ws.mjs" 2>&1 | Select-String -Pattern "MESSAGE|RESULT|CLOSE" | ForEach-Object { $_.Line }","description":"Final regression run"}

