import path from 'node:path'
import { fileURLToPath } from 'node:url'

import Websock from '../novnc/core/websock.js'

const here = path.dirname(fileURLToPath(import.meta.url))
const html = fs.readFileSync(path.join(here, '..', 'vnc-app.html'), 'utf8')

const failures = []
const check = (label, run) => {
  try {
    run()
    console.log(`OK    ${label}`)
  } catch (error) {
    failures.push(`${label}: ${error?.message ?? error}`)
    console.log(`FAIL  ${label}\n      ${error?.message ?? error}`)
  }
}

// ── extract and evaluate the shipped probe ───────────────────────────────────
const start = html.indexOf('/* ws-log:start')
const end = html.indexOf('/* ws-log:end */')
if (start === -1 || end === -1 || end < start) {
  console.error('FAIL  vnc-app.html no longer contains a ws-log:start/ws-log:end block')
  console.error('      the probe is extracted by those markers; restore them or update this test')
  process.exit(1)
}
const block = html.slice(html.indexOf('\n', start) + 1, end)

const win = { WebSocket: globalThis.WebSocket }
let Wrapped
try {
  Wrapped = new Function('window', `${block}\nreturn window.WebSocket;`)(win)
} catch (error) {
  console.error(`FAIL  the ws-log block in vnc-app.html does not evaluate: ${error?.message ?? error}`)
  process.exit(1)
}
