  try { socket.close() } catch { /* already gone */ }
}

if (failures.length > 0) {
  console.log('\nFAILURES:')
  for (const failure of failures) console.log(' -', failure)
  process.exit(1)
}
console.log('\nVNC WRAPPER TEST PASSED')
process.exit(0)
