```js
// ── the generic VNC connector ───────────────────────────────────────────────
/**
 * Runtime flavour of the shell this plugin is running in.
 *
 * Electron and Tauri both embed web content ("WebView"), but a plugin's client
 * code runs inside the app's renderer, where the only cross-origin embedding
 * primitive that behaves identically is the iframe; Electron's `<webview>` tag
 * additionally requires webviewTag to be enabled AND wires guest→embedder
 * messaging through ipc, not DOM postMessage — so the panel would gain a mode
 * that fails silently for half its control loop. The honest mapping is:
 *
 *   · Electron: "new window" = window.open() → a real BrowserWindow (a WebView)
 *     from the renderer; "embedded" = iframe inside the app's own web content.
 *   · Tauri: same — window.open() opens a real WebView window; iframe embeds.
 *   · Browser plugin: window.open() opens a new tab; iframe embeds.
 */
function detectRuntime() {
  if (typeof window === 'undefined') return 'browser'
  try {
    if (window.__TAURI__ !== undefined || window.__TAURI_INTERNALS__ !== undefined) return 'tauri'
  } catch { /* window props may be access-restricted */ }
  try {
    const ua = String(navigator?.userAgent ?? '')
    if (/\bElectron\//.test(ua)) return 'electron'
    if (typeof window.process === 'object' && window.process !== null && String(window.process.type) === 'renderer') return 'electron'
  } catch { /* same */ }
  return 'browser'
}
```

CONFIG defaults and normalization:

```js
const CONNECTOR_STORE_KEY = 'dsh-dzrobot-ssh/vnc-connector'

function loadConnectorConfig() {
  let saved = {}
  try {
    const text = typeof localStorage === 'undefined' ? null : localStorage.getItem(CONNECTOR_STORE_KEY)
    if (text !== null) saved = JSON.parse(text)
  } catch { saved = {} }
  return normalizeConnectorConfig(saved)
}

function normalizeConnectorConfig(raw) {
  const value = raw !== null && typeof raw === 'object' ? raw : {}
  const text = key => (typeof value[key] === 'string' ? value[key] : '')
  const host = text('host')
  return {
    scheme: value.scheme === 'wss' ? 'wss' : 'ws',
    host,
    port: text('port') === '' ? '6080' : text('port'),
    path: text('path') === '' ? 'websockify' : text('path'),
    password: text('password'),
    resolution: VNC_RESOLUTIONS.some(item => item.id === value.resolution) ? value.resolution : 'auto',
    scale: value.scale !== false,
  }
}

const VNC_RESOLUTIONS = [
  { id: 'auto' },
  { id: '1024x768' }, { id: '1280x720' }, { id: '1366x768' },
  { id: '1600x900' }, { id: '1920x1080' }, { id: '2560x1440' },
]
```

The component:

```js
function makeVncConnectorPanel(ctx, t) {
  return function VncConnectorPanel() {
    const [status, setStatus] = useState(undefined) // {origin}
    const [origin, setOrigin] = useState('')
    const [config, setConfig] = useState(loadConnectorConfig)
    const [phase, setPhase] = useState('idle')
    const [message, setMessage] = useState('')
    const [desktop, setDesktop] = useState('')
    const [fullscreenError, setFullscreenError] = useState('')
    const [runtimeKind] = useState(detectRuntime)
    const frameRef = useRef(null)
    const ready = useRef(false)
    const pending = useRef(null)
    const userStopped = useRef(false)

    // fetch origin
    useEffect(() => {
      let alive = true
      api('/status').then(payload => {
        if (!alive) return
        setStatus(payload)
        setOrigin(String(payload.origin ?? ''))
      }).catch(() => {})
      return () => { alive = false }
    }, [])

    const save = next => { setConfig(next); try { localStorage.setItem(CONNECTOR_STORE_KEY, JSON.stringify(next)) } catch {} }

    const patch = (key, value) => save({ ...config, [key]: value })

    const post = useCallback(payload => {
      const packet = { source: 'dzrobot-panel', ...payload }
      if (!ready.current) { pending.current = packet; return }
      try { frameRef.current?.contentWindow?.postMessage(packet, '*') } catch { /* frame not ready */ }
    }, [])

    const pushConfig = useCallback(() => {
      post({ type: 'config', config })
    }, [post, config])

    // on 'ready' from frame: flush queued (config), then if a connect was queued, send it
    useEffect(() => {
      const onMessage = event => {
        const data = event.data
        if (data === null || typeof data !== 'object' || data.source !== 'dzrobot-vnc-connect') return
        if (data.type === 'ready') {
          ready.current = true
          const queued = pending.current
          pending.current = null
          if (queued !== null) {
            try { frameRef.current?.contentWindow?.postMessage(queued, '*') } catch { /* gone */ }
          } else {
            pushConfig()
          }
        } else if (data.type === 'connecting') { setPhase('connecting'); setMessage(''); setFullscreenError('') }
        else if (data.type === 'connected') { setPhase('connected'); setDesktop(String(data.desktop ?? '')); setMessage(''); setFullscreenError('') }
        else if (data.type === 'credentials') { setPhase('auth'); setMessage(t('connNeedPassword')) }
        else if (data.type === 'credentials-sent') { setPhase('connecting'); setMessage('') }
        else if (data.type === 'disconnected') {
          if (userStopped.current) { userStopped.current = false; setPhase('idle'); setMessage('') }
          else {
            setPhase('disconnected')
            if (data.clean !== false) setMessage('')
            else if (data.closeReason) setMessage(String(data.closeReason))
            else if (data.closeCode !== undefined) setMessage(`${t('connDisconnected')}（WebSocket code ${data.closeCode}）`)
            else setMessage(data.reason || t('connDisconnected'))
          }
        } else if (data.type === 'failed') {
          setPhase('failed')
          setMessage(String(data.message ?? '失败'))
        }
        diag(`vnc-connector.${String(data.type ?? 'event')}`, {
          message: data.message, clean: data.clean,
          closeCode: data.closeCode, closeReason: data.closeReason,
          href: data.href, ws: data.ws,
        })
      }
      window.addEventListener('message', onMessage)
      return () => window.removeEventListener('message', onMessage)
    }, [pushConfig])
```

Wait — the deps: onMessage uses pushConfig which changes when config changes; adding config to deps would re-register each patch — acceptable but let me structure: the 'ready' handler flushes config via pushConfig; the listener deps [pushConfig] — re-registered on config change, fine. Actually there's a subtlety: `t` is stable. `pushConfig` = useCallback([post, config]) — changes on each patch → listener re-registered per keystroke. Harmless (removeEventListener/addEventListener), but a bit wasteful. Alternative: use refs for config. Simpler: keep a ref `configRef` updated via useEffect, and post uses configRef.current. Let me do:

```js
const configRef = useRef(config)
useEffect(() => { configRef.current = config }, [config])
```
and `pushConfig` = useCallback(() => post({ type: 'config', config: configRef.current }), [post]).

Then the message listener deps [pushConfig] — stable now (post is stable). 

connect:
```js
const connect = useCallback(() => {
  userStopped.current = false
  setPhase('connecting'); setMessage(''); setFullscreenError('')
  post({ type: 'config', config: configRef.current })
  post({ type: 'connect' })
}, [post])
```
But post queues if not ready: two packets — pending only holds ONE (pending.current = packet overwrites). Need a queue array. Modify post to queue array:

```js
const post = useCallback(payload => {
  const packet = { source: 'dzrobot-panel', ...payload }
  if (!ready.current) { pending.current.push(packet); return }
  ...
}, [])
```
with pending.current = [] initial. On ready: flush all.

Actually simpler: single 'connect' message carries config too? I defined document's protocol: 'config' + 'connect' separately, but 'connect' could accept message.config. Let me make the document's connect handler: `else if (message.type === 'connect') { if (message.config) applyConfig(message.config); connect() }`. Then the panel only ever posts ONE message: {type:'connect', config}. And on ready, flush queue. Cleaner. Also patch changes (scale/resolution) post specific messages.

Update the document: message handler 'config' stays for standalone sync, but panel uses connect+config. Let me adjust the document's message handler:

```js
if (message.type === 'config' ...) { apply config }
else if (message.type === 'connect') {
  if (message.config !== null && typeof message.config === 'object') applyConfig(message.config)
  connect()
}
```
where applyConfig is a function (extract from the current inline code). I'll refactor slightly in the HTML.

Fullscreen:
